import enum
from datetime import datetime, date
from sqlalchemy import Boolean, Date, DateTime, Enum, Float, ForeignKey, Integer, JSON, String, Text, UniqueConstraint, func
from pgvector.sqlalchemy import Vector
from ..config import get_settings
from sqlalchemy.orm import Mapped, mapped_column, relationship
from ..database import Base

class Role(str, enum.Enum): STUDENT="STUDENT"; ADMIN="ADMIN"
class DocumentStatus(str, enum.Enum): UPLOADED="UPLOADED"; PROCESSING="PROCESSING"; COMPLETED="COMPLETED"; FAILED="FAILED"
class Difficulty(str, enum.Enum): EASY="EASY"; MEDIUM="MEDIUM"; HARD="HARD"
class RelationshipType(str, enum.Enum): PREREQUISITE="PREREQUISITE"; RELATED="RELATED"; DEPENDS_ON="DEPENDS_ON"; ADVANCED_VERSION="ADVANCED_VERSION"; COMMON_MISTAKE="COMMON_MISTAKE"
class MistakeType(str, enum.Enum): CONCEPTUAL="CONCEPTUAL"; CALCULATION="CALCULATION"; LOGICAL="LOGICAL"; INTERPRETATION="INTERPRETATION"; TIME_MANAGEMENT="TIME_MANAGEMENT"; GUESSING="GUESSING"

class Timestamped:
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now(), onupdate=func.now())
class User(Timestamped, Base):
    __tablename__="users"; id: Mapped[int]=mapped_column(primary_key=True); name: Mapped[str]=mapped_column(String(120)); email: Mapped[str]=mapped_column(String(255), unique=True, index=True); password_hash: Mapped[str]=mapped_column(String(255)); role: Mapped[Role]=mapped_column(Enum(Role), default=Role.STUDENT)
class StudentProfile(Timestamped, Base):
    __tablename__="student_profiles"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id"), unique=True); current_level: Mapped[str]=mapped_column(String(30), default="MEDIUM"); target_companies: Mapped[list]=mapped_column(JSON, default=list); preferred_topics: Mapped[list]=mapped_column(JSON, default=list); overall_mastery: Mapped[float]=mapped_column(Float, default=0)
class Document(Base):
    __tablename__="documents"; id: Mapped[int]=mapped_column(primary_key=True); uploaded_by: Mapped[int]=mapped_column(ForeignKey("users.id"), index=True); filename: Mapped[str]=mapped_column(String(255)); file_type: Mapped[str]=mapped_column(String(20)); source_type: Mapped[str]=mapped_column(String(30), default="UPLOAD"); status: Mapped[DocumentStatus]=mapped_column(Enum(DocumentStatus), default=DocumentStatus.UPLOADED); extracted_text: Mapped[str|None]=mapped_column(Text, nullable=True); metadata_json: Mapped[dict]=mapped_column("metadata", JSON, default=dict); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now())
EmbeddingColumn=Vector(get_settings().embedding_dimensions).with_variant(JSON, "sqlite")
class DocumentChunk(Base):
    __tablename__="document_chunks"; id: Mapped[int]=mapped_column(primary_key=True); document_id: Mapped[int]=mapped_column(ForeignKey("documents.id", ondelete="CASCADE"), index=True); chunk_text: Mapped[str]=mapped_column(Text); topic: Mapped[str|None]=mapped_column(String(120), index=True); chunk_index: Mapped[int]=mapped_column(Integer); embedding: Mapped[list]=mapped_column(EmbeddingColumn, default=list); metadata_json: Mapped[dict]=mapped_column("metadata", JSON, default=dict); __table_args__=(UniqueConstraint("document_id","chunk_index"),)
class Concept(Base):
    __tablename__="concepts"; id: Mapped[int]=mapped_column(primary_key=True); name: Mapped[str]=mapped_column(String(150), unique=True, index=True); category: Mapped[str]=mapped_column(String(80)); description: Mapped[str]=mapped_column(Text, default=""); difficulty: Mapped[Difficulty]=mapped_column(Enum(Difficulty), default=Difficulty.MEDIUM); embedding: Mapped[list]=mapped_column(EmbeddingColumn, default=list)
class ConceptRelationship(Base):
    __tablename__="concept_relationships"; id: Mapped[int]=mapped_column(primary_key=True); source_concept_id: Mapped[int]=mapped_column(ForeignKey("concepts.id"), index=True); target_concept_id: Mapped[int]=mapped_column(ForeignKey("concepts.id"), index=True); relationship_type: Mapped[RelationshipType]=mapped_column(Enum(RelationshipType)); weight: Mapped[float]=mapped_column(Float, default=1.0); __table_args__=(UniqueConstraint("source_concept_id","target_concept_id","relationship_type"),)
class Question(Base):
    __tablename__="questions"; id: Mapped[int]=mapped_column(primary_key=True); concept_id: Mapped[int|None]=mapped_column(ForeignKey("concepts.id"), nullable=True); question_text: Mapped[str]=mapped_column(Text); options: Mapped[list]=mapped_column(JSON, default=list); correct_answer: Mapped[str]=mapped_column(String(500)); explanation: Mapped[str]=mapped_column(Text); difficulty: Mapped[Difficulty]=mapped_column(Enum(Difficulty), default=Difficulty.MEDIUM); company: Mapped[str|None]=mapped_column(String(100), nullable=True); question_type: Mapped[str]=mapped_column(String(50), default="QUANTITATIVE"); source_document_id: Mapped[int|None]=mapped_column(ForeignKey("documents.id"), nullable=True); generated_by_ai: Mapped[bool]=mapped_column(Boolean, default=False); approved: Mapped[bool]=mapped_column(Boolean, default=True); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now())
class QuestionAttempt(Base):
    __tablename__="question_attempts"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id"), index=True); question_id: Mapped[int]=mapped_column(ForeignKey("questions.id")); selected_answer: Mapped[str]=mapped_column(String(500)); is_correct: Mapped[bool]=mapped_column(Boolean); solving_time_seconds: Mapped[float]=mapped_column(Float); hints_used: Mapped[int]=mapped_column(Integer, default=0); confidence_score: Mapped[float]=mapped_column(Float, default=0.5); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now())
class Mistake(Base):
    __tablename__="mistakes"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id"), index=True); attempt_id: Mapped[int]=mapped_column(ForeignKey("question_attempts.id")); concept_id: Mapped[int|None]=mapped_column(ForeignKey("concepts.id"), nullable=True); mistake_type: Mapped[MistakeType]=mapped_column(Enum(MistakeType)); severity: Mapped[float]=mapped_column(Float); explanation: Mapped[str]=mapped_column(Text); recommended_action: Mapped[str]=mapped_column(Text); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now())
class LearningState(Base):
    __tablename__="learning_states"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id")); concept_id: Mapped[int]=mapped_column(ForeignKey("concepts.id")); mastery_score: Mapped[float]=mapped_column(Float, default=0); accuracy: Mapped[float]=mapped_column(Float, default=0); average_time: Mapped[float]=mapped_column(Float, default=0); hint_dependency: Mapped[float]=mapped_column(Float, default=0); confidence: Mapped[float]=mapped_column(Float, default=0); attempt_count: Mapped[int]=mapped_column(Integer, default=0); last_attempt_at: Mapped[datetime|None]=mapped_column(DateTime(timezone=True), nullable=True); trend: Mapped[str]=mapped_column(String(20), default="STABLE"); __table_args__=(UniqueConstraint("user_id","concept_id"),)
class RevisionPlan(Base):
    __tablename__="revision_plans"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id"), index=True); concept_id: Mapped[int]=mapped_column(ForeignKey("concepts.id")); priority: Mapped[int]=mapped_column(Integer); scheduled_date: Mapped[date]=mapped_column(Date, default=date.today); recommended_activity: Mapped[str]=mapped_column(Text); completion_status: Mapped[bool]=mapped_column(Boolean, default=False)
class MockTest(Base):
    __tablename__="mock_tests"; id: Mapped[int]=mapped_column(primary_key=True); title: Mapped[str]=mapped_column(String(255)); company: Mapped[str]=mapped_column(String(100)); difficulty: Mapped[Difficulty]=mapped_column(Enum(Difficulty)); duration_minutes: Mapped[int]=mapped_column(Integer); question_count: Mapped[int]=mapped_column(Integer); config: Mapped[dict]=mapped_column(JSON, default=dict); created_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now())
class MockTestQuestion(Base):
    __tablename__="mock_test_questions"; id: Mapped[int]=mapped_column(primary_key=True); mock_test_id: Mapped[int]=mapped_column(ForeignKey("mock_tests.id")); question_id: Mapped[int]=mapped_column(ForeignKey("questions.id")); sequence: Mapped[int]=mapped_column(Integer); __table_args__=(UniqueConstraint("mock_test_id","question_id"),)
class MockTestAttempt(Base):
    __tablename__="mock_test_attempts"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id")); mock_test_id: Mapped[int]=mapped_column(ForeignKey("mock_tests.id")); score: Mapped[float]=mapped_column(Float); accuracy: Mapped[float]=mapped_column(Float); average_time: Mapped[float]=mapped_column(Float); completed_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now())
class Readiness(Base):
    __tablename__="readiness"; id: Mapped[int]=mapped_column(primary_key=True); user_id: Mapped[int]=mapped_column(ForeignKey("users.id")); company: Mapped[str]=mapped_column(String(100)); readiness_score: Mapped[float]=mapped_column(Float); accuracy_score: Mapped[float]=mapped_column(Float); speed_score: Mapped[float]=mapped_column(Float); mastery_score: Mapped[float]=mapped_column(Float); mistake_recovery_score: Mapped[float]=mapped_column(Float); revision_consistency_score: Mapped[float]=mapped_column(Float); calculated_at: Mapped[datetime]=mapped_column(DateTime(timezone=True), server_default=func.now()); __table_args__=(UniqueConstraint("user_id","company"),)
